CREATE TABLE legal_persons (party_id TEXT PRIMARY KEY, canonical_name TEXT NOT NULL UNIQUE, person_type TEXT NOT NULL CHECK (person_type IN ('CORPORATION','LLC','INDIVIDUAL','PARTNERSHIP')), jurisdiction TEXT NOT NULL, active_flag INTEGER NOT NULL CHECK (active_flag IN (0,1)), created_at TEXT NOT NULL);

CREATE TABLE party_aliases (alias_id TEXT PRIMARY KEY, party_id TEXT NOT NULL, alias_name TEXT NOT NULL, alias_type TEXT NOT NULL CHECK (alias_type IN ('LEGAL_NAME','ABBREVIATION','DBA','CORPORATE_VARIANT','CAPACITY_VARIANT')), effective_date TEXT NOT NULL, end_date TEXT, FOREIGN KEY (party_id) REFERENCES legal_persons(party_id));

CREATE TABLE counsel (counsel_id TEXT PRIMARY KEY, full_name TEXT NOT NULL, bar_number TEXT NOT NULL UNIQUE, firm_id TEXT NOT NULL, firm_name TEXT NOT NULL, registration_status TEXT NOT NULL CHECK (registration_status IN ('ACTIVE','INACTIVE','SUSPENDED')), jurisdiction TEXT NOT NULL);

CREATE TABLE appearances (appearance_id TEXT PRIMARY KEY, case_id TEXT NOT NULL, party_id TEXT NOT NULL, counsel_id TEXT NOT NULL, appearance_type TEXT NOT NULL, event_id TEXT NOT NULL, event_date TEXT NOT NULL, capacity_type TEXT NOT NULL CHECK (capacity_type IN ('PLAINTIFF','DEFENDANT','INTERVENOR','CLAIMANT','RESPONDENT')), capacity_active INTEGER NOT NULL CHECK (capacity_active IN (0,1)), role_text TEXT NOT NULL, FOREIGN KEY (party_id) REFERENCES legal_persons(party_id), FOREIGN KEY (counsel_id) REFERENCES counsel(counsel_id));

CREATE TABLE service_roster_entries (roster_entry_id TEXT PRIMARY KEY, counsel_id TEXT, party_id TEXT, case_id TEXT, appearance_id TEXT, event_id TEXT, service_channel TEXT NOT NULL CHECK (service_channel IN ('CM_ECF','EMAIL','MAIL','HAND_DELIVERY','SUMMARY')), roster_version INTEGER NOT NULL, effective_at TEXT NOT NULL, entry_kind TEXT NOT NULL CHECK (entry_kind IN ('INDIVIDUAL','SUMMARY')), delivery_status TEXT NOT NULL CHECK (delivery_status IN ('ACTIVE','SUPERSEDED','REFERENCE_ONLY')), FOREIGN KEY (counsel_id) REFERENCES counsel(counsel_id), FOREIGN KEY (party_id) REFERENCES legal_persons(party_id), FOREIGN KEY (appearance_id) REFERENCES appearances(appearance_id));

