    43		  if (isExtract)
    44		    {
    45		      if (cp != (unsigned char *)name)
    46			cp--;
    47		      *cp = 0; /* terminate: lose final period */
    48		    }
    49		  else if (*cp != 0)
    50		    retvalue = 2;
    51		  
    52		  if (p1) /* we jumped via compression */
    53		    *pp = p1;
    54		  else
    55		    *pp = p;
