    57		  return retvalue;
    58		}
    59	
    60	      label_type = l & 0xc0;
    61	      
    62	      if (label_type == 0xc0) /* pointer */
    63		{ 
    64		  if (!CHECK_LEN(header, p, plen, 1))
    65		    return 0;
