    67		  /* get offset */
    68		  l = (l&0x3f) << 8;
    69		  l |= *p++;
    70		  
    71		  if (!p1) /* first jump, save location to go back to */
    72		    p1 = p;
    73		      
    74		  hops++; /* break malicious infinite loops */
    75		  if (hops > 255)
