   397	static unsigned char *do_doctor(unsigned char *p, int count, struct dns_header *header, size_t qlen, char *name, int *doctored)
   398	{
   399	  int i, qtype, qclass, rdlen;
   400	
   401	  for (i = count; i != 0; i--)
   402	    {
   403	      if (name && option_bool(OPT_LOG))
   404		{
   405		  if (!extract_name(header, qlen, &p, name, 1, 10))
   406		    return 0;
   407		}
   408	      else if (!(p = skip_name(p, header, qlen, 10)))
   409		return 0; /* bad packet */
   410	      
   411	      GETSHORT(qtype, p); 
   412	      GETSHORT(qclass, p);
   413	      p += 4; /* ttl */
   414	      GETSHORT(rdlen, p);
   415	      
   416	      if (qclass == C_IN && qtype == T_A)
   417		{
   418		  struct doctor *doctor;
   419		  struct in_addr addr;
   420		  
   421		  if (!CHECK_LEN(header, p, qlen, INADDRSZ))
   422		    return 0;
   423		  
   424		  /* alignment */
   425		  memcpy(&addr, p, INADDRSZ);
   426		  
   427		  for (doctor = daemon->doctors; doctor; doctor = doctor->next)
   428		    {
   429		      if (doctor->end.s_addr == 0)
   430			{
   431			  if (!is_same_net(doctor->in, addr, doctor->mask))
   432			    continue;
   433			}
   434		      else if (ntohl(doctor->in.s_addr) > ntohl(addr.s_addr) || 
   435			       ntohl(doctor->end.s_addr) < ntohl(addr.s_addr))
   436			continue;
   437		      
   438		      addr.s_addr &= ~doctor->mask.s_addr;
   439		      addr.s_addr |= (doctor->out.s_addr & doctor->mask.s_addr);
   440		      /* Since we munged the data, the server it came from is no longer authoritative */
   441		      header->hb3 &= ~HB3_AA;
   442		      *doctored = 1;
   443		      memcpy(p, &addr, INADDRSZ);
   444		      break;
   445		    }
   446		}
   447	      else if (qtype == T_TXT && name && option_bool(OPT_LOG))
   448		{
   449		  unsigned char *p1 = p;
   450		  if (!CHECK_LEN(header, p1, qlen, rdlen))
   451		    return 0;
   452		  while ((p1 - p) < rdlen)
   453		    {
   454		      unsigned int i, len = *p1;
   455		      unsigned char *p2 = p1;
   456		      if ((p1 + len - p) >= rdlen)
   457		        return 0; /* bad packet */
   458		      /* make counted string zero-term  and sanitise */
   459		      for (i = 0; i < len; i++)
   460			{
   461			  if (!isprint((int)*(p2+1)))
   462			    break;
   463			  
   464			  *p2 = *(p2+1);
   465			  p2++;
   466			}
   467		      *p2 = 0;
   468		      my_syslog(LOG_INFO, "reply %s is %s", name, p1);
   469		      /* restore */
   470		      memmove(p1 + 1, p1, i);
   471		      *p1 = len;
   472		      p1 += len+1;
   473		    }
   474		}		  
   475	      
   476	      if (!ADD_RDLEN(header, p, qlen, rdlen))
   477		 return 0; /* bad packet */
   478	    }
   479	  
   480	  return p; 
   481	}
