   483	static int find_soa(struct dns_header *header, size_t qlen, char *name, int *doctored)
   484	{
   485	  unsigned char *p;
   486	  int qtype, qclass, rdlen;
   487	  unsigned long ttl, minttl = ULONG_MAX;
