    41	char *get_null_terminated(const uint8_t **data, size_t *size) {
    42	#define STR_SIZE 75
    43	  if (*size < STR_SIZE || (int)*size < 0) {
    44	    return NULL;
    45	  }
    46	
    47	  char *new_s = malloc(STR_SIZE + 1);
    48	  memcpy(new_s, *data, STR_SIZE);
    49	  new_s[STR_SIZE] = '\0';
    50	
    51	  *data = *data+STR_SIZE;
    52	  *size -= STR_SIZE;
    53	  return new_s;
    54	}
