    61	  char *new_s = malloc(to_get);
    62	  memcpy(new_s, *data, to_get);
    63	
    64	  pointer_arr[pointer_idx++] = (void*)new_s;
    65	  
    66	  *data = *data + to_get;
    67	  *size -= to_get;
    68	
    69	  return new_s;
    70	}
