#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#define CHECK_LEN(header, pp, plen, len) \
    ((size_t)((pp) - (unsigned char *)(header) + (len)) <= (plen))

#define MAXDNAME 1025

struct dns_header {
    uint16_t id;
    uint8_t hb3, hb4;
    uint16_t qdcount, ancount, nscount, arcount;
};

int extract_name(struct dns_header *header, size_t plen, unsigned char **pp, 
                 char *name, int isExtract, int extrabytes) {
  unsigned char *cp = (unsigned char *)name, *p = *pp, *p1 = NULL;
  unsigned int j, l, namelen = 0, hops = 0;
  int retvalue = 1;

  if (isExtract)
    *cp = 0;

  while (1) { 
    unsigned int label_type;

    if (!CHECK_LEN(header, p, plen, 1))
      return 0;

    if ((l = *p++) == 0) 
    /* end marker */
    {
      /* check that there are the correct no. of bytes after the name */
      if (!CHECK_LEN(header, p1 ? p1 : p, plen, extrabytes))
        return 0;

      if (isExtract)
        {
          if (cp != (unsigned char *)name)
            cp--;
          *cp = 0; /* terminate: lose final period */
        }
      else if (*cp != 0)
        retvalue = 2;

      if (p1) /* we jumped via compression */
        *pp = p1;
      else
        *pp = p;

      return retvalue;
    }

    label_type = l & 0xc0;

    if (label_type == 0xc0) /* pointer */
    { 
      if (!CHECK_LEN(header, p, plen, 1))
        return 0;

      /* get offset */
      l = (l&0x3f) << 8;
      l |= *p++;

      if (!p1) /* first jump, save location to go back to */
        p1 = p;

      hops++; /* break malicious infinite loops */
      if (hops > 255)
        return 0;

      p = l + (unsigned char *)header;
    }
    else if (label_type == 0x00)
    { /* label_type = 0 -> label. */
      namelen += l + 1; /* include period */
      if (namelen >= MAXDNAME)
        return 0;
      if (!CHECK_LEN(header, p, plen, l))
        return 0;

      for(j=0; j<l; j++, p++)
        if (isExtract)
          {
            unsigned char c = *p;
#ifdef HAVE_DNSSEC
            if (option_bool(OPT_DNSSEC_VALID))
              {
                if (c == 0 || c == '.' || c == NAME_ESCAPE)
                  {
                    *cp++ = NAME_ESCAPE;
                    *cp++ = c+1;
                  }
                else
                  *cp++ = c; 
              }
            else
#endif
            if (c != 0 && c != '.')
              *cp++ = c;
            else
              return 0;
          }
        else 
          {
            unsigned char c1 = *cp, c2 = *p;

            if (c1 == 0)
              retvalue = 2;
            else 
              {
                cp++;
                if (c1 >= 'A' && c1 <= 'Z')
                  c1 += 'a' - 'A';
#ifdef HAVE_DNSSEC
                if (option_bool(OPT_DNSSEC_VALID) && c1 == NAME_ESCAPE)
                  c1 = (*cp++)-1;
#endif

                if (c2 >= 'A' && c2 <= 'Z')
                  c2 += 'a' - 'A';

                if (c1 != c2)
                  retvalue =  2;
              }
          }

      if (isExtract)
        *cp++ = '.';
      else if (*cp != 0 && *cp++ != '.')
        retvalue = 2;
    }
    else
      return 0; /* label types 0x40 and 0x80 not supported */
  }
}

int main() {
    struct dns_header header;
    unsigned char *p = NULL;
    char *name = malloc(76);  // Heap buffer, ASAN will detect overflow
    if (!name) {
        perror("malloc");
        return 1;
    }

    memset(&header, 0, sizeof(header));
    header.id = 0x1234;

    // Build DNS name: 78 labels of "A"
    unsigned char name_wire[157];
    memset(name_wire, 0, sizeof(name_wire));

    unsigned char *wp = name_wire;
    for (int i = 0; i < 78; i++) {
        *wp++ = 0x01;  // label length
        *wp++ = 'A';   // label data
    }
    *wp++ = 0x00;  // end marker

    p = name_wire;

    printf("Calling extract_name with heap buffer size %d\n", (int)76);
    printf("Wire format name size: %zu bytes\n", (size_t)(wp - name_wire));

    int result = extract_name(&header, wp - name_wire + 1, &p, name, 1, 1);

    printf("Result: %d\n", result);
    if (result > 0)
        printf("Name buffer: %s\n", name);

    free(name);
    return 0;
}

