183	 */
184	function parseHeadersInput(inputKey, inputOptions) {
185	    /** @type {string}*/
186	    const rawHeadersString = core.getInput(inputKey, inputOptions) || '';
187	    const headerStrings = rawHeadersString
188	        .split('\n')
189	        .map(line => line.trim())
190	        .filter(line => line !== '');
191	    return headerStrings
192	        .reduce((map, line) => {
193	            const seperator = line.indexOf(':');
194	            const key = line.substring(0, seperator).trim().toLowerCase();
195	            const value = line.substring(seperator + 1).trim();
196	            if (map.has(key)) {
197	                map.set(key, [map.get(key), value].join(', '));
198	            } else {
199	                map.set(key, value);
200	            }
201	            return map;
202	        }, new Map());
203	}
